  /** How far the sum of their figures is above the cap; 0.00 when it is not, or is n/a. */
  protected excessOf(p: Person): string {
    const total = this.uncappedDueCents(p);
    const cap = this.capCents();
    return money(total === null || cap === null ? 0 : Math.max(0, total - cap));
  }

  protected overdueOf(p: Person): Overdue {
    return this.overdueByPerson().get(p.id) ?? { count: 0, cents: 0 };
  }

  protected splitOf(p: Person): Split {
    return this.splitByPerson().get(p.id) ?? { settled: 0, open: 0 };
  }

  /**
   * Their score: their settled figures (in hundreds) less 5 for every overdue claim of theirs that counts,
   * rounded half to even to a whole number.
   */
  protected scoreOf(p: Person): number {
    // in cents, 10000 to a point
    const units = this.splitOf(p).settled - 50000 * this.overdueOf(p).count;
    const floor = Math.floor(units / 10000);
    const rest = units - floor * 10000;
    const score = rest > 5000 || (rest === 5000 && floor % 2 !== 0) ? floor + 1 : floor;
    return score;
  }

  protected agedOf(p: Person): Aged {
    return this.agedByPerson().get(p.id) ?? { upTo30: 0, upTo60: 0, over60: 0 };
  }

  /**
   * Compares the snapshots of the two dates; a blank to-date compares with now. Re-read from the store
   * first, so every person's snapshots and due-total are as the store holds them; the old lines are gone meanwhile.
   */
  protected async compareSnapshots(from: string, to: string): Promise<void> {
 * anything and calls {@link #recordChanges} once it has, which audits, after the change's own
 * lines, a ROLLUP line for each person whose figures (overdue-total included) moved (in the order
 * they were added) and a TOTALS line when the sheet's totals moved, then, while the sheet has an alert
 * threshold, an ALERT line for each person (in list order) whose due-total went from at or below it (or
 * none) to above it.
 */
@Service
public class RollupService {

    /**
     * A person's figures; a null due-total is n/a; the overdue-total is the dues of their overdue claims;
     * settled is the dues of their SETTLED claims, overdue count how many of their claims are overdue.
     */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal,
